#include "scarlett_unwind64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m;assert(m.map(0x10000,0x4000,3)==GuestMemory64::Fault::none);auto put=[&](uint64_t a,uint64_t v,unsigned n){std::array<uint8_t,8>b{};for(unsigned i=0;i<n;++i)b[i]=v>>(8*i);assert(m.write(a,std::span<uint8_t>(b).first(n))==GuestMemory64::Fault::none);};auto get=[&](uint64_t a){std::array<uint8_t,8>b{};assert(m.read(a,b)==GuestMemory64::Fault::none);uint64_t v=0;for(unsigned i=0;i<8;++i)v|=uint64_t(b[i])<<(8*i);return v;};uint64_t f=0;put(0x11000+152,0x12000,8);put(0x12000,0x12345,8);assert(unwindProlog64(m,0,0,0,0x11000,f));assert(get(0x11000+152)==0x12008&&get(0x11000+248)==0x12345);for(unsigned op:{4,5}){put(0x10100,0x200,4);put(0x10104,0x300,4);put(0x10108,0x400,4);put(0x10400,1|(8<<8)|((op==4?3:4)<<16),4);put(0x10404,8|(op<<8)|(3<<12),2);put(0x10406,op==4?2:16,op==4?2:4);put(0x10404+(op==4?4:6),0x3204,2);put(0x11000+152,0x12000,8);put(0x12010,0xabcdef,8);put(0x12020,0x45678,8);assert(unwindProlog64(m,0x10000,0x10208,0x10100,0x11000,f));assert(get(0x11000+144)==0xabcdef&&get(0x11000+248)==0x45678&&get(0x11000+152)==0x12028);}std::cout<<"V85H unwind tests passed\n";}
